def backfill_card_numbers(apps, schema_editor):
    """F592 为历史卡片按项目补齐自增编号 C-1/C-2…"""
    TaskCard = apps.get_model("projects", "TaskCard")
    projects = TaskCard.objects.values_list("board__project_id", flat=True).distinct()
    for project_id in projects:
        if project_id is None:
            continue
        cards = TaskCard.objects.filter(board__project_id=project_id).order_by("created_at", "id")
        for idx, card in enumerate(cards, start=1):
            if card.number is None:
                TaskCard.objects.filter(pk=card.pk).update(number=idx)


